package com.hibernate.ecommerce.service;import com.hibernate.ecommerce.dto.ClientDTO;import com.hibernate.ecommerce.mapper.ClientMapper;import com.hibernate.ecommerce.model.Client;import com.hibernate.ecommerce.repository.ClientRepository;import org.springframework.stereotype.Service;import java.util.List;@Servicepublic class ClientService implements IClientService{    private final ClientRepository clientRepository;    public ClientService(ClientRepository clientRepository) {        this.clientRepository = clientRepository;    }    @Override    public ClientDTO addClient(ClientDTO dto) {        if(dto == null) return null;        if(clientRepository.existsByEmail(dto.getEmail())){            throw new RuntimeException("Email already exists");        }        Client client = new Client();        client.setName(dto.getName());        client.setEmail(dto.getEmail());        client.setPhone(dto.getPhone());        Client save = clientRepository.save(client);        return ClientMapper.toDTO(save);    }    @Override    public ClientDTO findClientById(Long id) {        Client search = clientRepository.findById(id)                .orElseThrow(RuntimeException::new);        return ClientMapper.toDTO(search);    }    @Override    public List<ClientDTO> findAllClient() {        List<Client> all = clientRepository.findAll();        return all.stream()                .map(ClientMapper::toDTO)                .toList();    }    @Override    public ClientDTO updateClient(Long id, ClientDTO dto) {        if(dto == null) return null;        Client search = clientRepository.findById(id)                .orElseThrow(RuntimeException::new);        search.setName(dto.getName());        search.setPhone(dto.getPhone());        search.setEmail(dto.getEmail());        Client save = clientRepository.save(search);        return ClientMapper.toDTO(save);    }    @Override    public void deleteClient(Long id) {        if(clientRepository.existsById(id)){            clientRepository.deleteById(id);        }else{            throw new RuntimeException("Client with id:"+id+" are not exists");        }    }}